-- ============================================================================
--  Shop Yangu Kenya — database setup
--
--  Generated by scripts/build-sql.js on 2026-11-25.
--  Do not edit by hand: change the files in db/ and run that script again.
--
--  HOW TO USE THIS FILE
--
--    1. In Neon, open your project, then "SQL Editor" in the left sidebar.
--    2. Open this file in any plain text editor, select all, copy.
--    3. Paste it into the SQL editor and press Run.
--
--  You should see "Success" (or "APPLIED"). Running it a second time is safe:
--  it will say "Already applied — nothing to do" and skip the rest.
--
--  The whole file runs as one transaction. If any line fails, nothing at all
--  is applied and your database is left exactly as it was.

--  Creates the tables, the calculations and the access rules. After this,
--  the site has somewhere to keep shops, products, sales and customers, but
--  no shop yet. The next file adds one to look at.
-- ============================================================================

create table if not exists app_schema (
  file       text primary key,
  applied_at timestamptz not null default now(),
  checksum   text
);

begin;

do $mig$
begin
  if exists (select 1 from app_schema where file = 'apply-all.sql' and checksum = '9d528342ea4b8ad8') then
    raise notice 'Already applied — nothing to do.';
    return;
  end if;

-- ============================== db/001_schema.sql ==============================

-- ============================================================================
--  Shop Yangu Kenya — 001_schema.sql
--
--  Run this FIRST, in a fresh Neon database, before 002_functions.sql.
--  See docs/02-sql-scripts.md for the exact steps.
--
--  Design rules this file keeps, from the product spec (§6):
--
--    · Money is numeric(12,2). Never a float, never integer cents.
--    · Instants are timestamptz. Business dates (a sale's date, an expiry)
--      are plain date — a receipt belongs to a day, not a moment.
--    · Every table that belongs to a shop carries shop_id, and every query
--      runs under row-level security (003_rls.sql), so one shop can never
--      read another shop's rows even if the API has a bug.
--    · A sale line snapshots the name, price and cost at the moment of the
--      sale, so editing a product later cannot rewrite history.
--    · receipt_no is unique per shop and never reused.
--
--  It is safe to re-run: everything is IF NOT EXISTS, and the enums are
--  created inside a DO block that tolerates them already existing.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 0. Extensions
-- ---------------------------------------------------------------------------

-- gen_random_uuid() is in core Postgres 13+, which Neon runs. pgcrypto is
-- created anyway so older projects behave the same.
create extension if not exists pgcrypto;

-- citext gives case-insensitive email columns, so "Owner@Shop.co.ke" and
-- "owner@shop.co.ke" cannot become two accounts.
create extension if not exists citext;

-- ---------------------------------------------------------------------------
-- 1. Enumerations
--
--    Enums rather than free text: a typo in a payment method should fail at
--    the database, not silently create a fourth method that no report counts.
-- ---------------------------------------------------------------------------

do $$
begin
  if not exists (select 1 from pg_type where typname = 'login_role') then
    create type login_role as enum ('owner', 'super_admin');
  end if;

  if not exists (select 1 from pg_type where typname = 'payment_method') then
    create type payment_method as enum ('cash', 'mpesa', 'card');
  end if;

  if not exists (select 1 from pg_type where typname = 'po_status') then
    create type po_status as enum ('draft', 'ordered', 'received');
  end if;

  if not exists (select 1 from pg_type where typname = 'etims_status') then
    create type etims_status as enum ('pending', 'sent', 'failed');
  end if;

  if not exists (select 1 from pg_type where typname = 'mpesa_till_type') then
    create type mpesa_till_type as enum ('paybill', 'till');
  end if;

  if not exists (select 1 from pg_type where typname = 'mpesa_status') then
    create type mpesa_status as enum ('pending', 'success', 'failed', 'cancelled', 'timeout');
  end if;

  if not exists (select 1 from pg_type where typname = 'otp_purpose') then
    create type otp_purpose as enum ('signup', 'signin');
  end if;

  if not exists (select 1 from pg_type where typname = 'stock_reason') then
    create type stock_reason as enum ('sale', 'purchase', 'adjustment', 'return', 'import');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- 2. The shop, and the one login that belongs to it
--
--    One login per shop, as the product decided: no staff accounts, no roles
--    to switch between. The only other role is the platform's own super
--    admin, which is not a shop and is not created by the sign-up flow.
-- ---------------------------------------------------------------------------

create table if not exists shops (
  id                uuid primary key default gen_random_uuid(),
  name              text        not null,
  branch            text        not null default 'Main branch',
  phone             text,
  kra_pin           text,
  -- Plan. Price is read from here, never hard-coded in markup.
  plan_kes          numeric(12,2) not null default 1500,
  plan_started_on   date        not null default current_date,
  plan_renews_on    date,
  -- The shop is soft-deleted: a duka that stops paying keeps its receipts.
  suspended_at      timestamptz,
  suspended_reason  text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

comment on column shops.plan_kes is 'Monthly price in whole shillings. The client said this will change: the app must read it, never hard-code it.';

-- Settings live in their own row so a partial update cannot rewrite the shop's
-- identity by accident, and so adding a preference is a new column, not a JSON
-- blob nobody can query.
create table if not exists shop_settings (
  shop_id             uuid primary key references shops (id) on delete cascade,
  allow_credit        boolean not null default true,
  ask_customer        boolean not null default false,
  sms_receipt         boolean not null default true,
  offline_selling     boolean not null default true,
  -- Which M-Pesa till the till screen defaults to (set in 006 / docs/06).
  default_mpesa_till  uuid,
  updated_at          timestamptz not null default now()
);

create table if not exists logins (
  id                 uuid primary key default gen_random_uuid(),
  -- A super admin belongs to no shop. A shop owner must have one.
  shop_id            uuid references shops (id) on delete cascade,
  email              citext      not null unique,
  name               text        not null,
  role               login_role  not null default 'owner',
  -- Null until the first OTP or magic link is used. Until then the account
  -- exists but cannot hold a session.
  email_verified_at  timestamptz,
  last_seen_at       timestamptz,
  -- The password, hashed with scrypt. Null until the address confirms its first
  -- sign-up and chooses one; an account without a password signs in with an
  -- emailed code instead, so this column can stay empty for ever without
  -- breaking anything.
  --
  -- Two columns, because scrypt's cost is in the salt and the parameters: a
  -- single string would have to be parsed back apart to verify.
  password_hash      text,
  password_salt      text,
  password_params    text,
  password_set_at    timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint super_admin_has_no_shop
    check ((role = 'super_admin' and shop_id is null) or (role = 'owner' and shop_id is not null))
);

create index if not exists logins_shop_idx on logins (shop_id);

-- A sign-up that has been emailed a code but has not started yet. Keeping it
-- separate means an unverified email can never own a shop name or a login.
create table if not exists pending_signups (
  id           uuid primary key default gen_random_uuid(),
  email        citext      not null unique,
  shop_name    text        not null,
  person_name  text        not null,
  -- Chosen on the sign-up form, held here until the emailed code proves the
  -- address is real, then copied onto the login. Never readable: same scrypt
  -- columns as logins, for the same reason.
  password_hash text,
  password_salt text,
  password_params text,
  expires_at   timestamptz not null,
  created_at   timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- 3. Email sign-in: a six-digit code, and a link
--
--    Both are stored HASHED. If the database is ever dumped, the dump cannot
--    be used to sign in. Both are single-use and both expire.
--
--    Why both: a code suits a phone on a flaky connection, and a link suits
--    a laptop. The shop asked for "OTP / sign-in links" — this is the pair.
-- ---------------------------------------------------------------------------

create table if not exists login_codes (
  id           uuid primary key default gen_random_uuid(),
  -- A code belongs to an existing login (a sign-in) or to a pending sign-up
  -- (the first email a shop gets). Exactly one of the two, never both: an
  -- address that has only been emailed but not verified owns nothing yet.
  login_id     uuid        references logins (id) on delete cascade,
  pending_id   uuid        references pending_signups (id) on delete cascade,
  -- An HMAC of the six digits with the server's pepper. Never the digits.
  code_hash    text        not null,
  purpose      otp_purpose not null,
  expires_at   timestamptz not null,
  attempts     smallint    not null default 0,
  consumed_at  timestamptz,
  created_at   timestamptz not null default now(),
  constraint login_code_has_one_owner
    check ((login_id is null) <> (pending_id is null)),
  constraint signup_code_is_for_signups
    check (pending_id is null or purpose = 'signup')
);

create index if not exists login_codes_login_idx on login_codes (login_id, created_at desc);
create index if not exists login_codes_pending_idx on login_codes (pending_id, created_at desc);

create table if not exists login_tokens (
  id           uuid primary key default gen_random_uuid(),
  -- Same rule as login_codes: a sign-in link, or a sign-up link.
  login_id     uuid        references logins (id) on delete cascade,
  pending_id   uuid        references pending_signups (id) on delete cascade,
  -- An HMAC of a 32-byte random token. The URL carries the raw value once.
  token_hash   text        not null unique,
  purpose      otp_purpose not null,
  expires_at   timestamptz not null,
  consumed_at  timestamptz,
  created_at   timestamptz not null default now(),
  constraint login_token_has_one_owner
    check ((login_id is null) <> (pending_id is null)),
  constraint signup_link_is_for_signups
    check (pending_id is null or purpose = 'signup')
);

create index if not exists login_tokens_login_idx on login_tokens (login_id, created_at desc);
create index if not exists login_tokens_pending_idx on login_tokens (pending_id, created_at desc);

comment on table login_tokens is 'Magic links. Single use, 30 minutes, hashed at rest.';

-- ---------------------------------------------------------------------------
-- 4. Sessions
--
--    A session is the cookie the app carries. It records the device, so the
--    super-admin screen can show "who is logged in" honestly, and so a shop
--    can end a session it does not recognise.
-- ---------------------------------------------------------------------------

create table if not exists sessions (
  id            uuid primary key default gen_random_uuid(),
  -- Only the hash of the cookie value is stored.
  token_hash    text        not null unique,
  login_id      uuid        not null references logins (id) on delete cascade,
  shop_id       uuid        references shops (id) on delete cascade,
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  expires_at    timestamptz not null default (now() + interval '30 days'),
  revoked_at    timestamptz,
  ip            text,
  user_agent    text
);

create index if not exists sessions_login_idx   on sessions (login_id);
create index if not exists sessions_live_idx    on sessions (expires_at desc) where revoked_at is null;

-- ---------------------------------------------------------------------------
-- 5. Catalogue
-- ---------------------------------------------------------------------------

create table if not exists categories (
  id        uuid primary key default gen_random_uuid(),
  shop_id   uuid        not null references shops (id) on delete cascade,
  name      text        not null,
  position  smallint    not null default 0,
  unique (shop_id, name)
);

create table if not exists products (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid          not null references shops (id) on delete cascade,
  category_id    uuid          references categories (id) on delete set null,
  sku            text          not null,
  name           text          not null,
  unit           text          not null default 'piece',
  cost_price     numeric(12,2) not null default 0 check (cost_price >= 0),
  selling_price  numeric(12,2) not null default 0 check (selling_price >= 0),
  -- The shelf count. Every change also writes a stock_movements row, so a
  -- number that looks wrong can be explained.
  qty            numeric(12,3) not null default 0,
  reorder_level  numeric(12,3) not null default 0,
  expiry_date    date,
  barcode        text,
  active         boolean       not null default true,
  created_at     timestamptz   not null default now(),
  updated_at     timestamptz   not null default now(),
  unique (shop_id, sku)
);

create index if not exists products_shop_idx  on products (shop_id) where active;
create index if not exists products_name_trgm on products (shop_id, lower(name));

create table if not exists stock_movements (
  id          bigserial   primary key,
  shop_id     uuid        not null references shops (id) on delete cascade,
  product_id  uuid        not null references products (id) on delete cascade,
  reason      stock_reason not null,
  -- Positive for stock in, negative for stock out. qty_after is the level
  -- the shelf was left at, so a movement is self-explaining.
  change      numeric(12,3) not null,
  qty_after   numeric(12,3) not null,
  note        text,
  sale_id     uuid,
  login_id    uuid        references logins (id) on delete set null,
  at          timestamptz not null default now()
);

create index if not exists stock_movements_product_idx on stock_movements (product_id, at desc);

-- ---------------------------------------------------------------------------
-- 6. Suppliers and purchase orders
-- ---------------------------------------------------------------------------

create table if not exists suppliers (
  id             uuid primary key default gen_random_uuid(),
  shop_id        uuid          not null references shops (id) on delete cascade,
  name           text          not null,
  phone          text,
  terms          text          not null default 'Cash on delivery',
  balance_owed   numeric(12,2) not null default 0,
  created_at     timestamptz   not null default now()
);

create table if not exists purchase_orders (
  id           uuid primary key default gen_random_uuid(),
  shop_id      uuid          not null references shops (id) on delete cascade,
  supplier_id  uuid          references suppliers (id) on delete set null,
  no           text          not null,
  status       po_status     not null default 'draft',
  ordered_on   date,
  received_on  date,
  total        numeric(12,2) not null default 0,
  created_at   timestamptz   not null default now(),
  unique (shop_id, no)
);

create table if not exists po_lines (
  id          uuid primary key default gen_random_uuid(),
  po_id       uuid          not null references purchase_orders (id) on delete cascade,
  product_id  uuid          references products (id) on delete set null,
  name        text          not null,
  qty         numeric(12,3) not null check (qty > 0),
  unit_cost   numeric(12,2) not null check (unit_cost >= 0)
);

-- ---------------------------------------------------------------------------
-- 7. Customers and credit
-- ---------------------------------------------------------------------------

create table if not exists customers (
  id            uuid primary key default gen_random_uuid(),
  shop_id       uuid          not null references shops (id) on delete cascade,
  name          text          not null,
  phone         text,
  -- 0 means "no credit": a walk-in can buy but cannot owe.
  credit_limit  numeric(12,2) not null default 0,
  -- Money the customer already owed when the shop started using the system.
  -- It is not a sale — no goods moved through the till today — so it is kept
  -- apart from the sales ledger and added in when the balance is worked out.
  opening_balance numeric(12,2) not null default 0,
  -- Derived from openings, sales and payments, but stored so a report does not
  -- have to sum a year of history. recalc_customer_balance() keeps it right.
  balance       numeric(12,2) not null default 0,
  since         date          not null default current_date,
  notes         text,
  created_at    timestamptz   not null default now()
);

create index if not exists customers_shop_idx on customers (shop_id, name);

-- ---------------------------------------------------------------------------
-- 8. Sales
--
--    A sale is one row. Its money is split into sale_lines (what was sold)
--    and sale_payments (how it was paid). A shortfall is credit_amount.
-- ---------------------------------------------------------------------------

create table if not exists sales (
  id            uuid primary key default gen_random_uuid(),
  shop_id       uuid          not null references shops (id) on delete cascade,
  receipt_no    text          not null,
  sold_at       timestamptz   not null default now(),
  sold_on       date          not null default current_date,
  customer_id   uuid          references customers (id) on delete set null,
  -- The name as printed, so a renamed customer does not rewrite a receipt.
  customer_name text          not null default 'Walk-in',
  subtotal      numeric(12,2) not null,
  vat           numeric(12,2) not null default 0,
  total         numeric(12,2) not null,
  credit_amount numeric(12,2) not null default 0 check (credit_amount >= 0),
  created_by    uuid          references logins (id) on delete set null,
  created_at    timestamptz   not null default now(),
  unique (shop_id, receipt_no),
  -- VAT is 16% of the gross. Checked, not assumed: a sale that does not add
  -- up is a bug, and it should fail here rather than in a KRA report.
  constraint vat_adds_up check (abs(subtotal + vat - total) < 0.02)
);

create index if not exists sales_shop_date_idx on sales (shop_id, sold_on desc, sold_at desc);

create table if not exists sale_lines (
  id                 uuid primary key default gen_random_uuid(),
  sale_id            uuid          not null references sales (id) on delete cascade,
  product_id         uuid          references products (id) on delete set null,
  -- Snapshots. A receipt must never change because the price changed today.
  name_snapshot      text          not null,
  qty                numeric(12,3) not null check (qty > 0),
  unit_price         numeric(12,2) not null check (unit_price >= 0),
  unit_cost_snapshot numeric(12,2) not null default 0
);

create index if not exists sale_lines_sale_idx on sale_lines (sale_id);

create table if not exists sale_payments (
  id       uuid primary key default gen_random_uuid(),
  sale_id  uuid          not null references sales (id) on delete cascade,
  method   payment_method not null,
  amount   numeric(12,2) not null check (amount > 0),
  -- For M-Pesa, the Safaricom receipt and the request it came from.
  mpesa_receipt text,
  mpesa_request_id uuid
);

create index if not exists sale_payments_sale_idx on sale_payments (sale_id);

-- One M-Pesa payment per M-Pesa request. The callback can be retried, so this
-- index (not the application) is what guarantees the money lands exactly once.
create unique index if not exists sale_payments_mpesa_request_uidx
  on sale_payments (mpesa_request_id) where mpesa_request_id is not null;

-- Money a customer pays against what they already owe. Separate from a sale
-- payment: it settles an old receipt, it is not part of a new sale.
create table if not exists credit_payments (
  id           uuid primary key default gen_random_uuid(),
  shop_id      uuid          not null references shops (id) on delete cascade,
  customer_id  uuid          not null references customers (id) on delete cascade,
  received_at  timestamptz   not null default now(),
  amount       numeric(12,2) not null check (amount > 0),
  method       payment_method not null,
  note         text,
  received_by  uuid          references logins (id) on delete set null
);

create index if not exists credit_payments_customer_idx on credit_payments (customer_id, received_at desc);

-- ---------------------------------------------------------------------------
-- 9. Expenses
-- ---------------------------------------------------------------------------

create table if not exists expenses (
  id          uuid primary key default gen_random_uuid(),
  shop_id     uuid          not null references shops (id) on delete cascade,
  spent_on    date          not null default current_date,
  description text          not null,
  category    text          not null default 'Other',
  amount      numeric(12,2) not null check (amount > 0),
  created_at  timestamptz   not null default now()
);

create index if not exists expenses_shop_date_idx on expenses (shop_id, spent_on desc);

-- ---------------------------------------------------------------------------
-- 10. KRA eTIMS
--
--     The sandbox integration lands here later. The table exists now so a
--     sale can be recorded and marked "not yet transmitted" without a
--     migration on the day eTIMS is switched on.
-- ---------------------------------------------------------------------------

create table if not exists etims_transmissions (
  id         uuid primary key default gen_random_uuid(),
  sale_id    uuid          not null references sales (id) on delete cascade,
  status     etims_status  not null default 'pending',
  signature  text,
  invoice_no text,
  sent_at    timestamptz,
  response   jsonb,
  created_at timestamptz   not null default now()
);

create index if not exists etims_status_idx on etims_transmissions (status, created_at);

-- ---------------------------------------------------------------------------
-- 11. M-Pesa, one till per shop
--
--     A shop's till number, passkey, consumer key and secret belong to the
--     shop's row here — not to the platform's environment. Two dukas have
--     two tills, and each prompt must go out under the shop whose counter it
--     is. docs/06-mpesa-per-shop.md explains the flow and why the callback
--     carries a per-shop secret.
-- ---------------------------------------------------------------------------

create table if not exists mpesa_tills (
  id                uuid primary key default gen_random_uuid(),
  shop_id           uuid        not null references shops (id) on delete cascade,
  label             text        not null default 'Main till',
  -- 5-7 digits. For a Buy Goods (Till) number, this is the store number.
  shortcode         text        not null check (shortcode ~ '^[0-9]{5,7}$'),
  type              mpesa_till_type not null default 'till',
  -- Safaricom issues a different passkey per shortcode.
  passkey           text        not null,
  -- The Daraja app credentials. Stored encrypted at rest by the API (see
  -- docs/06); the column is text because the ciphertext is base64.
  consumer_key      text        not null,
  consumer_secret   text        not null,
  -- Random per shop. It is the only thing in an unauthenticated Safaricom
  -- callback URL that proves which shop the payment belongs to.
  callback_secret   text        not null unique,
  environment       text        not null default 'sandbox' check (environment in ('sandbox', 'production')),
  is_default        boolean     not null default false,
  active            boolean     not null default true,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (shop_id, shortcode)
);

-- Only one default till per shop.
create unique index if not exists mpesa_one_default_per_shop
  on mpesa_tills (shop_id) where is_default;

create table if not exists mpesa_requests (
  id                  uuid primary key default gen_random_uuid(),
  shop_id             uuid          not null references shops (id) on delete cascade,
  till_id             uuid          references mpesa_tills (id) on delete set null,
  sale_id             uuid          references sales (id) on delete set null,
  -- Safaricom's two identifiers. checkout_request_id is what the callback
  -- quotes, and it is unique, so a repeated callback cannot double-credit.
  checkout_request_id text          unique,
  merchant_request_id text,
  phone               text          not null,
  amount              numeric(12,2) not null check (amount > 0),
  account_ref         text          not null,
  status              mpesa_status  not null default 'pending',
  result_code         integer,
  result_desc         text,
  -- The Safaricom receipt (e.g. "NLJ7RT61SV"). Unique where present: the same
  -- payment can never be posted twice.
  mpesa_receipt       text unique,
  raw                 jsonb,
  created_at          timestamptz   not null default now(),
  completed_at        timestamptz
);

create index if not exists mpesa_requests_shop_idx on mpesa_requests (shop_id, created_at desc);
create index if not exists mpesa_requests_pending_idx on mpesa_requests (created_at) where status = 'pending';

-- ---------------------------------------------------------------------------
-- 12. Audit log
--
--     Append-only. No update, no delete: a rule enforced by grants in 004 and
--     by having no endpoint that writes to it directly.
-- ---------------------------------------------------------------------------

create table if not exists audit_entries (
  id        bigserial   primary key,
  shop_id   uuid        references shops (id) on delete cascade,
  login_id  uuid        references logins (id) on delete set null,
  at        timestamptz not null default now(),
  action    text        not null,
  detail    text
);

create index if not exists audit_shop_idx on audit_entries (shop_id, at desc);

-- ---------------------------------------------------------------------------
-- 13. Platform-level notes for the super admin
-- ---------------------------------------------------------------------------

create table if not exists admin_notes (
  id         uuid primary key default gen_random_uuid(),
  shop_id    uuid        references shops (id) on delete cascade,
  login_id   uuid        references logins (id) on delete cascade,
  note       text        not null,
  created_by uuid        references logins (id) on delete set null,
  created_at timestamptz not null default now()
);

-- ============================== db/002_functions.sql ==============================

-- ============================================================================
--  Shop Yangu Kenya — 002_functions.sql
--
--  Run this AFTER 001_schema.sql. See docs/02-sql-scripts.md.
--
--  These functions are where the app's rules live when they matter:
--
--    · a sale decrements stock in the same transaction as the sale
--    · a sale can never oversell the last packet
--    · a receipt number is allocated inside the transaction, never reused
--    · a customer's balance is recalculated from history, not incremented
--      by hand, so it cannot drift
--
--  The API calls these with SELECT/INSERT; it never writes stock or balances
--  directly. That is what makes "two tills cannot sell the same last packet"
--  true rather than hopeful.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. updated_at, kept honest by the database rather than the caller
-- ---------------------------------------------------------------------------

create or replace function touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists shops_touch on shops;
create trigger shops_touch before update on shops
  for each row execute function touch_updated_at();

drop trigger if exists logins_touch on logins;
create trigger logins_touch before update on logins
  for each row execute function touch_updated_at();

drop trigger if exists products_touch on products;
create trigger products_touch before update on products
  for each row execute function touch_updated_at();

-- ---------------------------------------------------------------------------
-- 2. Receipt numbers
--
--    S-0001, per shop, from a counter row. Taking the counter with
--    `for update` serialises two tills starting a sale at the same instant: the
--    second waits, then gets the next number. A receipt number is therefore
--    never handed out twice, even under load, and never reused after a void.
-- ---------------------------------------------------------------------------

create table if not exists shop_counters (
  shop_id        uuid primary key references shops (id) on delete cascade,
  last_receipt   integer not null default 0
);

create or replace function next_receipt_no(p_shop uuid)
returns text
language plpgsql
as $$
declare
  n integer;
begin
  insert into shop_counters (shop_id, last_receipt)
  values (p_shop, 0)
  on conflict (shop_id) do nothing;

  update shop_counters
     set last_receipt = last_receipt + 1
   where shop_id = p_shop
  returning last_receipt into n;

  return 'S-' || lpad(n::text, 4, '0');
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Stock
--
--    One function, one reason: stock only ever moves through here, so every
--    change leaves a movement row that says why. The quantity is checked
--    against zero when the caller says `allow_negative = false`, which is what
--    the till does — a shop with no matches cannot sell matches.
-- ---------------------------------------------------------------------------

create or replace function apply_stock(
  p_shop      uuid,
  p_product   uuid,
  p_change    numeric,
  p_reason    stock_reason,
  p_note      text default null,
  p_sale      uuid default null,
  p_login     uuid default null,
  p_allow_negative boolean default false
)
returns numeric
language plpgsql
as $$
declare
  v_after numeric;
begin
  update products
     set qty = qty + p_change
   where id = p_product and shop_id = p_shop
  returning qty into v_after;

  if not found then
    raise exception 'product % does not belong to shop %', p_product, p_shop
      using errcode = 'foreign_key_violation';
  end if;

  if v_after < 0 and not p_allow_negative then
    raise exception 'not enough stock for product %: % left, tried to take %',
      p_product, v_after - p_change, -p_change
      using errcode = 'check_violation';
  end if;

  insert into stock_movements (shop_id, product_id, reason, change, qty_after, note, sale_id, login_id)
  values (p_shop, p_product, p_reason, p_change, v_after, p_note, p_sale, p_login);

  update products set updated_at = now() where id = p_product;

  return v_after;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Recording a sale
--
--    Everything a till does, in one transaction:
--      · allocate the receipt number
--      · write the sale and its lines (snapshotting name, price and cost)
--      · take the stock, refusing to go below zero
--      · write the payments, and the credit if the customer did not cover it
--      · recalculate that customer's balance
--      · mark the sale as awaiting its eTIMS transmission
--      · write an audit entry
--
--    p_lines:    [{product_id, qty, unit_price, unit_cost, name}]
--    p_payments: [{method, amount, mpesa_receipt, mpesa_request_id}]
--
--    Money is passed as whole shillings and the VAT is computed here, not by
--    the client: a till that rounds differently from the books is a tax
--    problem waiting to happen.
-- ---------------------------------------------------------------------------

create or replace function record_sale(
  p_shop        uuid,
  p_login       uuid,
  p_customer    uuid,
  p_lines       jsonb,
  p_payments    jsonb,
  p_vat_rate    numeric default 0.16
)
returns sales
language plpgsql
as $$
declare
  v_sale        sales;
  v_line        jsonb;
  v_pay         jsonb;
  v_total       numeric(12,2) := 0;
  v_vat         numeric(12,2);
  v_subtotal    numeric(12,2);
  v_paid        numeric(12,2) := 0;
  v_credit      numeric(12,2);
  v_customer    customers;
  v_receipt     text;
  v_name        text;
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'a sale needs at least one line' using errcode = 'check_violation';
  end if;

  -- The customer, if there is one, must belong to this shop.
  if p_customer is not null then
    select * into v_customer from customers where id = p_customer and shop_id = p_shop;
    if not found then
      raise exception 'customer % is not this shop''s' , p_customer using errcode = 'foreign_key_violation';
    end if;
  end if;

  -- Total from the lines, not from the client's arithmetic.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_total := v_total + (coalesce((v_line->>'qty')::numeric, 0)
                        * coalesce((v_line->>'unit_price')::numeric, 0));
  end loop;

  if v_total <= 0 then
    raise exception 'a sale must total more than zero' using errcode = 'check_violation';
  end if;

  -- VAT is 16% of the gross, so what the customer sees is what is charged.
  v_vat      := round(v_total * p_vat_rate / (1 + p_vat_rate), 2);
  v_subtotal := v_total - v_vat;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments) loop
      v_paid := v_paid + coalesce((v_pay->>'amount')::numeric, 0);
    end loop;
  end if;

  v_credit := greatest(0, round(v_total - v_paid, 2));

  -- Credit needs somebody to owe it. A walk-in cannot.
  if v_credit > 0 and p_customer is null then
    raise exception 'a sale with % on credit needs a named customer', v_credit
      using errcode = 'check_violation';
  end if;

  if v_credit > 0 and v_customer.credit_limit > 0
     and v_customer.balance + v_credit > v_customer.credit_limit then
    raise exception 'that would take % over their credit limit of %',
      coalesce(v_customer.name, 'the customer'), v_customer.credit_limit
      using errcode = 'check_violation';
  end if;

  v_receipt := next_receipt_no(p_shop);

  insert into sales (shop_id, receipt_no, customer_id, customer_name, subtotal, vat, total,
                     credit_amount, created_by)
  values (p_shop, v_receipt, p_customer,
          coalesce(v_customer.name, 'Walk-in'),
          v_subtotal, v_vat, v_total, v_credit, p_login)
  returning * into v_sale;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    insert into sale_lines (sale_id, product_id, name_snapshot, qty, unit_price, unit_cost_snapshot)
    values (v_sale.id,
            (v_line->>'product_id')::uuid,
            coalesce(v_line->>'name', 'Item'),
            (v_line->>'qty')::numeric,
            (v_line->>'unit_price')::numeric,
            coalesce((v_line->>'unit_cost')::numeric, 0));

    -- Stock out, in the same transaction. This is the line that stops two
    -- tills overselling the last packet: the second one raises and rolls back.
    if (v_line->>'product_id') is not null then
      perform apply_stock(p_shop, (v_line->>'product_id')::uuid,
                          -((v_line->>'qty')::numeric), 'sale',
                          'Sold on ' || v_receipt, v_sale.id, p_login, false);
    end if;
  end loop;

  if p_payments is not null then
    for v_pay in select * from jsonb_array_elements(p_payments) loop
      if coalesce((v_pay->>'amount')::numeric, 0) > 0 then
        insert into sale_payments (sale_id, method, amount, mpesa_receipt, mpesa_request_id)
        values (v_sale.id,
                (v_pay->>'method')::payment_method,
                (v_pay->>'amount')::numeric,
                nullif(v_pay->>'mpesa_receipt', ''),
                nullif(v_pay->>'mpesa_request_id', '')::uuid);
      end if;
    end loop;
  end if;

  if v_credit > 0 then
    perform recalc_customer_balance(p_customer);
  end if;

  insert into etims_transmissions (sale_id, status) values (v_sale.id, 'pending');

  insert into audit_entries (shop_id, login_id, action, detail)
  values (p_shop, p_login, 'sale.recorded',
          v_receipt || ' · ' || v_total::text || ' · ' || case when v_credit > 0 then 'credit ' || v_credit::text else 'paid' end);

  return v_sale;
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Customer balances
--
--    Recalculated from history every time, rather than added to. A balance
--    that is computed cannot drift, and a nightly job is not required for it
--    to be right.
--
--      balance = credited sales
--              − payments against credit
--              − any cash paid at the time of those sales beyond the credit
-- ---------------------------------------------------------------------------

create or replace function recalc_customer_balance(p_customer uuid)
returns numeric
language plpgsql
as $$
declare
  v_balance numeric(12,2);
begin
  /* Opening balance + everything sold on credit − everything paid back.
     A shop that migrates from a paper book has customers who already owe;
     ignoring that would show a clean slate that is not true. */
  select (select c.opening_balance from customers c where c.id = p_customer)
       + coalesce(sum(s.credit_amount), 0)
       - coalesce((select sum(cp.amount) from credit_payments cp where cp.customer_id = p_customer), 0)
    into v_balance
    from sales s
   where s.customer_id = p_customer;

  update customers set balance = greatest(0, v_balance) where id = p_customer;
  return greatest(0, v_balance);
end;
$$;

create or replace function recalc_all_customer_balances(p_shop uuid)
returns integer
language plpgsql
as $$
declare
  c record;
  n integer := 0;
begin
  for c in select id from customers where shop_id = p_shop loop
    perform recalc_customer_balance(c.id);
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- When a customer pays off credit, their balance must follow immediately.
create or replace function credit_payment_touch_balance()
returns trigger
language plpgsql
as $$
begin
  perform recalc_customer_balance(new.customer_id);
  insert into audit_entries (shop_id, login_id, action, detail)
  values (new.shop_id, new.received_by, 'credit.paid',
          new.amount::text || ' by ' || new.method::text);
  return new;
end;
$$;

drop trigger if exists credit_payment_balance on credit_payments;
create trigger credit_payment_balance after insert on credit_payments
  for each row execute function credit_payment_touch_balance();

-- ---------------------------------------------------------------------------
-- 6. M-Pesa requests
--
--    Starting a prompt and finishing it are two steps, because Safaricom
--    answers twice: once when it accepts the request (CheckoutRequestID) and
--    once when the customer enters their PIN (the callback). Only the second
--    is money.
-- ---------------------------------------------------------------------------

create or replace function mpesa_start(
  p_till     uuid,
  p_phone    text,
  p_amount   numeric,
  p_account  text,
  p_sale     uuid default null
)
returns mpesa_requests
language plpgsql
as $$
declare
  v_till mpesa_tills;
  v_row  mpesa_requests;
begin
  select * into v_till from mpesa_tills where id = p_till and active;
  if not found then
    raise exception 'no active till %', p_till using errcode = 'no_data_found';
  end if;

  insert into mpesa_requests (shop_id, till_id, sale_id, phone, amount, account_ref)
  select t.shop_id, t.id, p_sale, p_phone, p_amount, p_account
    from mpesa_tills t where t.id = p_till
  returning * into v_row;

  return v_row;
end;
$$;

-- The callback. Idempotent by construction: checkout_request_id and
-- mpesa_receipt are unique, so a callback delivered twice changes nothing the
-- second time and cannot credit the same money twice.
create or replace function mpesa_complete(
  p_checkout_id  text,
  p_result_code  integer,
  p_result_desc  text,
  p_receipt      text,
  p_amount       numeric,
  p_phone        text,
  p_raw          jsonb
)
returns mpesa_requests
language plpgsql
as $$
declare
  v_row mpesa_requests;
  v_status mpesa_status;
begin
  select * into v_row from mpesa_requests where checkout_request_id = p_checkout_id;
  if not found then
    raise exception 'unknown checkout request %', p_checkout_id using errcode = 'no_data_found';
  end if;

  -- Already settled: return it unchanged. A retried callback is not an error.
  if v_row.status <> 'pending' then
    return v_row;
  end if;

  v_status := case
    when p_result_code = 0 then 'success'
    when p_result_code = 1032 then 'cancelled'
    when p_result_code in (1037, 1001) then 'timeout'
    else 'failed'
  end;

  update mpesa_requests
     set status = v_status,
         result_code = p_result_code,
         result_desc = p_result_desc,
         mpesa_receipt = p_receipt,
         raw = p_raw,
         completed_at = now()
   where id = v_row.id
  returning * into v_row;

  -- Money arrived. If this request was started against a sale, book it as that
  -- sale's payment now; the partial unique index on sale_payments.mpesa_request_id
  -- makes a replayed callback a no-op instead of a double credit.
  if v_status = 'success' then
    if v_row.sale_id is not null then
      insert into sale_payments (sale_id, method, amount, mpesa_receipt, mpesa_request_id)
      values (v_row.sale_id, 'mpesa', coalesce(p_amount, v_row.amount),
              p_receipt, v_row.id)
      on conflict (mpesa_request_id) where mpesa_request_id is not null do nothing;
    end if;

    if p_amount is not null and p_amount <> v_row.amount then
      insert into audit_entries (shop_id, action, detail)
      values (v_row.shop_id, 'mpesa.amount_mismatch',
              'asked for ' || v_row.amount::text || ', paid ' || p_amount::text
              || ' · ' || coalesce(p_receipt, ''));
    end if;
  end if;

  insert into audit_entries (shop_id, action, detail)
  values (v_row.shop_id, 'mpesa.' || v_status::text,
          coalesce(p_receipt, '') || ' · ' || coalesce(p_amount, 0)::text);

  return v_row;
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Sign-in codes are single use
-- ---------------------------------------------------------------------------

create or replace function consume_login_code(p_login uuid, p_code_hash text)
returns boolean
language plpgsql
as $$
declare
  v_row login_codes;
begin
  select * into v_row
    from login_codes
   where login_id = p_login
     and consumed_at is null
     and expires_at > now()
   order by created_at desc
   limit 1;

  if not found then
    return false;
  end if;

  -- Five wrong guesses and the code is dead. Brute-forcing six digits is
  -- otherwise a few seconds of work.
  if v_row.attempts >= 5 then
    update login_codes set consumed_at = now() where id = v_row.id;
    return false;
  end if;

  if v_row.code_hash <> p_code_hash then
    update login_codes set attempts = attempts + 1 where id = v_row.id;
    return false;
  end if;

  update login_codes set consumed_at = now() where id = v_row.id;
  return true;
end;
$$;

-- ---------------------------------------------------------------------------
-- 8. Views the API and the super-admin screen read
-- ---------------------------------------------------------------------------

-- Sales as the till screen wants them: one row per sale, payments folded in.
create or replace view v_sales as
select
  s.id,
  s.shop_id,
  s.receipt_no,
  s.sold_at,
  s.sold_on,
  s.customer_id,
  s.customer_name,
  s.subtotal,
  s.vat,
  s.total,
  s.credit_amount,
  coalesce(
    jsonb_agg(distinct jsonb_build_object('m', sp.method, 'amt', sp.amount))
      filter (where sp.id is not null), '[]'::jsonb) as payments,
  count(distinct sl.id) as line_count,
  coalesce(sum(sl.qty), 0) as items
from sales s
left join sale_payments sp on sp.sale_id = s.id
left join sale_lines sl    on sl.sale_id = s.id
group by s.id;

-- Today's numbers, per shop: what the dashboard card shows.
create or replace view v_daily_takings as
select
  s.shop_id,
  s.sold_on,
  count(*)                                  as receipts,
  sum(s.total)                              as gross,
  sum(s.vat)                                as vat,
  sum(s.credit_amount)                      as credit,
  sum(s.total - s.vat
      - coalesce((select sum(sl.qty * sl.unit_cost_snapshot)
                    from sale_lines sl where sl.sale_id = s.id), 0)) as gross_profit
from sales s
group by s.shop_id, s.sold_on;

-- "Who is logged in": live sessions with the shop and the person.
create or replace view v_active_sessions as
select
  ss.id                as session_id,
  ss.login_id,
  l.email,
  l.name               as person,
  l.role,
  ss.shop_id,
  sh.name              as shop_name,
  ss.created_at        as signed_in_at,
  ss.last_seen_at,
  ss.expires_at,
  ss.ip,
  ss.user_agent
from sessions ss
join logins l  on l.id = ss.login_id
left join shops sh on sh.id = ss.shop_id
where ss.revoked_at is null
  and ss.expires_at > now();

-- The super-admin dashboard: one row per shop.
create or replace view v_shop_overview as
select
  sh.id,
  sh.name,
  sh.branch,
  sh.phone,
  sh.plan_kes,
  sh.created_at,
  sh.suspended_at,
  l.email              as owner_email,
  l.name               as owner_name,
  l.last_seen_at       as owner_last_seen,
  (select count(*) from sessions s
     where s.shop_id = sh.id and s.revoked_at is null and s.expires_at > now()) as live_sessions,
  (select count(*) from products p where p.shop_id = sh.id and p.active)          as products,
  (select count(*) from sales s where s.shop_id = sh.id)                          as sales,
  (select coalesce(sum(s.total), 0) from sales s where s.shop_id = sh.id)         as lifetime_sales,
  (select coalesce(sum(s.total), 0) from sales s
     where s.shop_id = sh.id and s.sold_on = current_date)                        as sales_today,
  (select coalesce(sum(c.balance), 0) from customers c where c.shop_id = sh.id)   as credit_out,
  exists (select 1 from mpesa_tills t where t.shop_id = sh.id and t.active)       as has_mpesa
from shops sh
left join logins l on l.shop_id = sh.id and l.role = 'owner';

-- ============================== db/003_rls.sql ==============================

-- ===========================================================================
--  003 — Roles, grants, row-level security
--
--  Run this third, after 001 and 002.
--
--  Two things are being protected here, and neither is theoretical:
--
--   1. MONEY MUST NOT BE DELETABLE. The API is an ordinary web app: a wrong
--      route, a bad merge or a clever request must not be able to remove a
--      receipt, a payment or an audit line. The database refuses on its own,
--      whatever the application thinks is allowed.
--
--   2. M-PESA SECRETS MUST NOT BE READABLE BY THE APP. A till's passkey and
--      consumer secret are the shop's money. The API role cannot even SELECT
--      those columns; it sees v_mpesa_tills (no secrets) and calls two
--      security-definer functions that use the real values on its behalf.
--
--  Roles:
--    the Neon owner  runs migrations and drills. Owns everything, bypasses RLS.
--    syk_app         the API. This is the only role the public server uses.
--
--  Shop isolation is enforced twice: the API scopes every query by shop_id,
--  and these policies return nothing if it ever forgets. The second net is
--  what makes the first one safe to get wrong.
-- ===========================================================================

do $$
begin
  if not exists (select 1 from pg_roles where rolname = 'syk_app') then
    create role syk_app nologin;
  end if;
end
$$;

revoke create on schema public from public;
grant  usage on schema public to syk_app;

-- ---------------------------------------------------------------------------
-- 1. What the API may touch
-- ---------------------------------------------------------------------------

grant select, insert, update on
  shops,
  shop_settings,
  logins,
  categories,
  products,
  suppliers,
  purchase_orders,
  po_lines,
  customers,
  expenses,
  etims_transmissions,
  mpesa_requests,
  admin_notes
to syk_app;

-- Stock is a ledger: append, never rewrite.
grant select, insert on stock_movements to syk_app;

-- ---------------------------------------------------------------------------
-- 2. What the API may only add to
--
--    Sales, their lines and payments, credit payments and the audit log are
--    append-only. A correction is a new row — a return, a credit payment, a
--    stock adjustment — never an edit of history. That is what lets the
--    dashboard numbers be trusted a year from now.
-- ---------------------------------------------------------------------------

grant select, insert on
  sales,
  sale_lines,
  sale_payments,
  credit_payments,
  audit_entries
to syk_app;

-- ---------------------------------------------------------------------------
-- 3. Sessions and one-time codes
--    Housekeeping: last_seen_at, revoked_at, consumed_at, and a sweep of
--    expired rows. Nothing here is history anybody needs later.
-- ---------------------------------------------------------------------------

grant select, insert, update, delete on
  sessions,
  login_codes,
  login_tokens,
  pending_signups
to syk_app;

grant usage, select on all sequences in schema public to syk_app;

-- ---------------------------------------------------------------------------
-- 4. M-Pesa credentials stay behind the wall
-- ---------------------------------------------------------------------------

revoke all on mpesa_tills from syk_app, public;

create or replace view v_mpesa_tills as
select
  t.id,
  t.shop_id,
  t.label,
  t.type,
  t.shortcode,
  t.environment,
  t.is_default,
  t.active,
  t.created_at,
  t.updated_at,
  -- Says whether secrets are in place, without revealing any of them.
  (t.passkey <> '' and t.consumer_key <> '' and t.consumer_secret <> ''
     and t.callback_secret <> '') as configured
from mpesa_tills t;

grant select on v_mpesa_tills to syk_app;

-- ---------------------------------------------------------------------------
-- 5. Views the API reads
--
--    security_invoker = true means the view runs with the *caller's* rights,
--    so the RLS policies in section 7 still apply through it. A definer view
--    here would quietly hand one shop another shop's totals.
--
--    Recreated here rather than in 002 because the flag is a security
--    decision, and it belongs next to the policies it depends on.
-- ---------------------------------------------------------------------------

create or replace view v_sales
with (security_invoker = true) as
select
  s.id, s.shop_id, s.receipt_no, s.sold_at, s.sold_on,
  s.customer_id, s.customer_name,
  s.subtotal, s.vat, s.total, s.credit_amount,
  coalesce(jsonb_agg(distinct jsonb_build_object('m', sp.method, 'amt', sp.amount))
             filter (where sp.id is not null), '[]'::jsonb) as payments,
  count(distinct sl.id)     as line_count,
  coalesce(sum(sl.qty), 0)  as items
from sales s
left join sale_payments sp on sp.sale_id = s.id
left join sale_lines sl    on sl.sale_id = s.id
group by s.id;

create or replace view v_daily_takings
with (security_invoker = true) as
select
  s.shop_id, s.sold_on,
  count(*)     as receipts,
  sum(s.total) as gross,
  sum(s.vat)   as vat,
  sum(s.credit_amount) as credit,
  sum(s.total - s.vat
      - coalesce((select sum(sl.qty * sl.unit_cost_snapshot)
                    from sale_lines sl where sl.sale_id = s.id), 0)) as gross_profit
from sales s
group by s.shop_id, s.sold_on;

-- A shop's own open sessions (the "signed-in devices" list on settings).
create or replace view v_active_sessions
with (security_invoker = true) as
select
  ss.id            as session_id,
  ss.login_id,
  l.email,
  l.name           as person,
  l.role,
  ss.shop_id,
  sh.name          as shop_name,
  ss.created_at    as signed_in_at,
  ss.last_seen_at,
  ss.expires_at,
  ss.ip,
  ss.user_agent
from sessions ss
join logins l  on l.id = ss.login_id
left join shops sh on sh.id = ss.shop_id
where ss.revoked_at is null
  and ss.expires_at > now();

grant select on v_sales, v_daily_takings, v_active_sessions to syk_app;

-- ---------------------------------------------------------------------------
-- 6. The super admin
--
--    A platform operator legitimately reads across every shop, so it cannot be
--    a shop-scoped query. It is not a wide-open view either: each read checks
--    a flag the API sets for that one request, and refuses otherwise. If a
--    shop's session is ever mistakenly upgraded to that flag, the shop list
--    still comes back, but it is the operator's own data — and the flag is set
--    only on routes that proved a super_admin login first.
-- ---------------------------------------------------------------------------

create or replace function is_super_admin()
returns boolean
language sql
stable
as $$
  select coalesce(current_setting('syk.super_admin', true), '') = 'on';
$$;

create or replace function require_super_admin()
returns void
language plpgsql
as $$
begin
  if not is_super_admin() then
    raise exception 'this read is for the super admin only'
      using errcode = 'insufficient_privilege';
  end if;
end;
$$;

-- The operator's shop list: one row per shop, with the numbers that matter.
create or replace function admin_shops()
returns table (
  id              uuid,
  name            text,
  branch          text,
  phone           text,
  plan_kes        numeric,
  created_at      timestamptz,
  suspended_at    timestamptz,
  owner_email     text,
  owner_name      text,
  owner_last_seen timestamptz,
  live_sessions   bigint,
  products        bigint,
  sales           bigint,
  lifetime_sales  numeric,
  sales_today     numeric,
  credit_out      numeric,
  has_mpesa       boolean
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform require_super_admin();

  return query
  select
    sh.id, sh.name, sh.branch, sh.phone, sh.plan_kes, sh.created_at, sh.suspended_at,
    l.email::text, l.name, l.last_seen_at,
    (select count(*) from sessions s
       where s.shop_id = sh.id and s.revoked_at is null and s.expires_at > now()),
    (select count(*) from products p where p.shop_id = sh.id and p.active),
    (select count(*) from sales s where s.shop_id = sh.id),
    (select coalesce(sum(s.total), 0) from sales s where s.shop_id = sh.id),
    (select coalesce(sum(s.total), 0) from sales s
       where s.shop_id = sh.id and s.sold_on = current_date),
    (select coalesce(sum(c.balance), 0) from customers c where c.shop_id = sh.id),
    exists (select 1 from mpesa_tills t where t.shop_id = sh.id and t.active)
  from shops sh
  left join logins l on l.shop_id = sh.id and l.role = 'owner'
  order by sh.created_at desc;
end;
$$;

-- "Who is logged in right now" — every live session, every shop.
create or replace function admin_sessions(p_live_only boolean default true)
returns table (
  session_id   uuid,
  login_id     uuid,
  email        text,
  person       text,
  role         login_role,
  shop_id      uuid,
  shop_name    text,
  signed_in_at timestamptz,
  last_seen_at timestamptz,
  expires_at   timestamptz,
  ip           text,
  user_agent   text,
  revoked_at   timestamptz
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform require_super_admin();

  return query
  select ss.id, ss.login_id, l.email::text, l.name, l.role, ss.shop_id, sh.name,
         ss.created_at, ss.last_seen_at, ss.expires_at, ss.ip, ss.user_agent,
         ss.revoked_at
    from sessions ss
    join logins l  on l.id = ss.login_id
    left join shops sh on sh.id = ss.shop_id
   where (not p_live_only)
      or (ss.revoked_at is null and ss.expires_at > now())
   order by ss.last_seen_at desc;
end;
$$;

-- Platform totals for the top of the admin screen.
create or replace function admin_totals()
returns table (
  shops        bigint,
  live_logins  bigint,
  sales_today  numeric,
  sales_all    numeric,
  credit_out   numeric,
  new_shops_7d bigint
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  perform require_super_admin();

  return query
  select
    (select count(*) from shops where suspended_at is null),
    (select count(*) from sessions where revoked_at is null and expires_at > now()),
    (select coalesce(sum(total), 0) from sales where sold_on = current_date),
    (select coalesce(sum(total), 0) from sales),
    (select coalesce(sum(balance), 0) from customers),
    (select count(*) from shops where created_at > now() - interval '7 days');
end;
$$;

revoke all on function is_super_admin()            from public;
revoke all on function require_super_admin()       from public;
revoke all on function admin_shops()               from public;
revoke all on function admin_sessions(boolean)     from public;
revoke all on function admin_totals()              from public;

grant execute on function is_super_admin()        to syk_app;
grant execute on function admin_shops()           to syk_app;
grant execute on function admin_sessions(boolean) to syk_app;
grant execute on function admin_totals()          to syk_app;

-- ---------------------------------------------------------------------------
-- 7. M-Pesa: the two functions that touch a secret
-- ---------------------------------------------------------------------------

create or replace function mpesa_start(
  p_till     uuid,
  p_phone    text,
  p_amount   numeric,
  p_account  text,
  p_sale     uuid default null
)
returns mpesa_requests
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_till mpesa_tills;
  v_row  mpesa_requests;
begin
  select * into v_till from mpesa_tills where id = p_till and active;
  if not found then
    raise exception 'no active till %', p_till using errcode = 'no_data_found';
  end if;

  insert into mpesa_requests (shop_id, till_id, sale_id, phone, amount, account_ref)
  values (v_till.shop_id, v_till.id, p_sale, p_phone, p_amount, p_account)
  returning * into v_row;

  return v_row;
end;
$$;

-- A Safaricom callback carries only the URL it was given; that path holds a
-- random secret. This is how the API turns that secret into a till, and so
-- into the credentials to verify the payment — without ever being able to
-- list or read the secrets themselves.
create or replace function mpesa_till_by_secret(p_secret text)
returns table (
  till_id     uuid,
  shop_id     uuid,
  shortcode   text,
  till_type   mpesa_till_type,
  environment text,
  is_default  boolean
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.id, t.shop_id, t.shortcode, t.type, t.environment, t.is_default
    from mpesa_tills t
   where t.callback_secret = p_secret
     and t.active;
$$;

-- The STK password is base64(shortcode + passkey + timestamp), per shop.
-- Computed in the database so the passkey never travels to the app.
create or replace function mpesa_stk_password(p_till uuid, p_timestamp text)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_passkey text;
  v_short   text;
begin
  select t.passkey, t.shortcode into v_passkey, v_short
    from mpesa_tills t where t.id = p_till and t.active;

  if v_passkey is null then
    raise exception 'no active till %', p_till using errcode = 'no_data_found';
  end if;

  return encode(convert_to(v_short || v_passkey || p_timestamp, 'UTF8'), 'base64');
end;
$$;

-- The Daraja consumer key and secret for one till, for the OAuth call only.
-- Granted to the API because it must POST them to Safaricom; scoped to one
-- till id so it cannot be used to list every shop's credentials.
create or replace function mpesa_credentials(p_till uuid)
returns table (consumer_key text, consumer_secret text, shortcode text, type mpesa_till_type)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.consumer_key, t.consumer_secret, t.shortcode, t.type
    from mpesa_tills t where t.id = p_till and t.active;
$$;

-- The callback secret for one till, so the prompt can build its own callback
-- URL. Used once per prompt; the secret itself never reaches the browser.
create or replace function callback_secret(p_till uuid)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.callback_secret from mpesa_tills t where t.id = p_till and t.active;
$$;

revoke all on function mpesa_credentials(uuid) from public;
revoke all on function callback_secret(uuid)   from public;
grant execute on function mpesa_credentials(uuid) to syk_app;
grant execute on function callback_secret(uuid)   to syk_app;

revoke all on function mpesa_start(uuid, text, numeric, text, uuid) from public;
revoke all on function mpesa_till_by_secret(text)                  from public;
revoke all on function mpesa_stk_password(uuid, text)              from public;
revoke all on function mpesa_complete(text, integer, text, text, numeric, text, jsonb) from public;
revoke all on function record_sale(uuid, uuid, uuid, jsonb, jsonb, numeric) from public;
revoke all on function consume_login_code(uuid, text) from public;

grant execute on function mpesa_start(uuid, text, numeric, text, uuid)            to syk_app;
grant execute on function mpesa_till_by_secret(text)                              to syk_app;
grant execute on function mpesa_stk_password(uuid, text)                          to syk_app;
grant execute on function mpesa_complete(text, integer, text, text, numeric, text, jsonb) to syk_app;
grant execute on function record_sale(uuid, uuid, uuid, jsonb, jsonb, numeric)    to syk_app;
grant execute on function consume_login_code(uuid, text)                          to syk_app;

-- ---------------------------------------------------------------------------
-- 8. The audit log is append-only, enforced
--
--    Grants alone would not stop the table owner, and a future teammate will
--    run queries as the owner. So the table refuses edits itself.
-- ---------------------------------------------------------------------------

create or replace function audit_entries_append_only()
returns trigger
language plpgsql
as $$
begin
  raise exception 'audit_entries is append-only: % is not allowed', tg_op
    using errcode = 'insufficient_privilege';
end;
$$;

drop trigger if exists audit_entries_no_update on audit_entries;
create trigger audit_entries_no_update
  before update or delete on audit_entries
  for each row execute function audit_entries_append_only();

-- ---------------------------------------------------------------------------
-- 9. Row-level security
--
--    The API sets two things for the duration of a request, in the same
--    transaction as the query:
--
--      select set_config('syk.shop_id', '<uuid>', true);   -- shop routes
--      select set_config('syk.super_admin', 'on', true);   -- admin routes
--
--    Both are transaction-local (the `true`), so a pooled connection cannot
--    carry one request's shop into the next request.
-- ---------------------------------------------------------------------------

create or replace function current_shop()
returns uuid
language sql
stable
as $$
  select nullif(current_setting('syk.shop_id', true), '')::uuid;
$$;

alter table sales           enable row level security;
alter table sale_lines      enable row level security;
alter table sale_payments   enable row level security;
alter table credit_payments enable row level security;
alter table customers       enable row level security;
alter table mpesa_requests  enable row level security;
alter table sessions        enable row level security;

-- The owner (migrations, drills, the Neon SQL editor) is not filtered: it is
-- how you fix a shop's data at 11pm. The API role always is.
create policy sales_shop_isolation on sales
  for all to syk_app
  using (shop_id = current_shop()) with check (shop_id = current_shop());

create policy sale_lines_shop_isolation on sale_lines
  for all to syk_app
  using (exists (select 1 from sales s where s.id = sale_lines.sale_id
                   and s.shop_id = current_shop()))
  with check (exists (select 1 from sales s where s.id = sale_lines.sale_id
                        and s.shop_id = current_shop()));

create policy sale_payments_shop_isolation on sale_payments
  for all to syk_app
  using (exists (select 1 from sales s where s.id = sale_payments.sale_id
                   and s.shop_id = current_shop()))
  with check (exists (select 1 from sales s where s.id = sale_payments.sale_id
                        and s.shop_id = current_shop()));

create policy credit_payments_shop_isolation on credit_payments
  for all to syk_app
  using (shop_id = current_shop()) with check (shop_id = current_shop());

create policy customers_shop_isolation on customers
  for all to syk_app
  using (shop_id = current_shop()) with check (shop_id = current_shop());

create policy sessions_shop_isolation on sessions
  for all to syk_app
  using (shop_id = current_shop()) with check (shop_id = current_shop());

-- M-Pesa requests are created by a definer function and finished by the
-- callback, which has no shop in scope until it has resolved the secret.
-- Reads are scoped; the two writes are opened narrowly.
create policy mpesa_requests_read on mpesa_requests
  for select to syk_app using (shop_id = current_shop());

create policy mpesa_requests_insert on mpesa_requests
  for insert to syk_app with check (true);

create policy mpesa_requests_update on mpesa_requests
  for update to syk_app using (true) with check (true);

create policy audit_entries_read on audit_entries
  for select to syk_app
  using (shop_id is null or shop_id = current_shop());

create policy audit_entries_write on audit_entries
  for insert to syk_app with check (true);

-- ---------------------------------------------------------------------------
-- 10. Housekeeping
-- ---------------------------------------------------------------------------

revoke truncate on all tables in schema public from syk_app;

comment on role syk_app is
  'The API role: sells, records, reads. Cannot delete money, edit history, or read M-Pesa secrets.';
comment on table logins is
  'One login per shop, role owner. Plus platform-level super_admin rows with shop_id null. No staff/cashier roles.';

  delete from app_schema where file = 'apply-all.sql';
  insert into app_schema (file, checksum, applied_at) values ('apply-all.sql', '9d528342ea4b8ad8', now());
  raise notice 'APPLIED.';
end
$mig$;

commit;
